INSERT INTO public.health_quotes (agency_id, quote_text, attribution, flavor) VALUES
  ('126794dd-25ff-47d2-a436-724499733365', 'Take care of your body. It''s the only place you have to live.', 'Jim Rohn', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'The body achieves what the mind believes.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Sweat is just fat crying.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Your body keeps score. Make it count something good today.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'I don''t count my sit-ups. I only start counting when it starts hurting. That''s when I start counting, because then it really counts.', 'Muhammad Ali', 'both'),
  ('126794dd-25ff-47d2-a436-724499733365', 'A one hour workout is 4% of your day. No excuses.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'The hardest lift of any kind is lifting your butt off the couch.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Discipline is choosing between what you want now and what you want most.', 'Abraham Lincoln', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Your future self is watching you right now through memories.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'The only bad workout is the one that didn''t happen.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'I have two muscles: agree and disagree. Today, choose agree with the gym.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Strength does not come from physical capacity. It comes from an indomitable will.', 'Gandhi', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'If it doesn''t challenge you, it doesn''t change you.', 'Fred DeVito', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Push yourself, because no one else is going to do it for you.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'My favorite exercise is a cross between a lunge and a crunch — I call it lunch.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'It''s going to be a journey. It''s not a sprint to get in shape.', 'Kerri Walsh Jennings', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Do something today that your future self will thank you for.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'The clock is ticking. Are you becoming the person you want to be?', 'Greg Plitt', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Yoga pants are causing women to be lazy, and not work out. Said no man ever, but you should work out anyway.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'The pain you feel today will be the strength you feel tomorrow.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Excuses don''t burn calories.', NULL, 'both'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Discipline equals freedom.', 'Jocko Willink', 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Health is the greatest of all possessions.', NULL, 'inspiring'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Bodies in motion stay in motion. Bodies on the couch stay on the couch and complain about the couch.', NULL, 'funny'),
  ('126794dd-25ff-47d2-a436-724499733365', 'Don''t wish for it. Work for it.', NULL, 'inspiring');
